  (* LPS 75d69e00, the channel-reader premise.  stdio_call_sound gained
     [m_channel_reader mo = true], so this file's replayed application of it is one argument
     short -- the only file in either chain to hit `stdio_call_sound` rather than `_post`.
     Measured before the edit, cold single-target from a verdict-grade staging:
       VOS-FAIL As/AsExit.v - Illegal application: "@stdio_call_sound" at line 85
     TWO sites, ax_sound_flush and as_exit_flush.  The four clean variants perform no write,
     carry no fd_lookup and conclude a bare t_exit, so they take NOTHING -- confirmed against
     the donor, whose reader sites are exactly its flush variants.
     `mo` is bound inside each theorem's own forall, so the premise CANNOT enter as a section
     hypothesis and both statements are written out; the About faithfulness control applies and
     its OLD arm is g3notes/bjrb-asexit-statements.txt, taken before this edit.
     DONOR, with its branch (rule 23c): a donor tree:
     projects/openssl/echconfiglist_parser/proofs/lib/Both/AsExit/AsExit.v:252-374.
     ITS DECOMPOSITION DIFFERS -- four runs with one cas_exit_lock and one unreg_call_sound,
     against this tree's FIVE runs with three CAS intermediates -- so it is a shape donor, not
     a hunk donor.  The three steps are this tree's own As/AsExitCas.v:47 cas_exit_lock (4 bytes
     at 0x714648), :74 cas_mu_lock and :98 cas_mu_unlock (8 bytes at 0x1bdaf0), each confirmed
     by its own W_ word constants pointing at the next run's start: W_77b94/98/9c before
     rX3g@0x77ba0 and W_77f04/08/0c before rX4f@0x77f10.  NOTHING IS RE-ENCODED. *)
  Theorem ax_sound_flush : forall vals R M msF mo (pending : list byte) (code : word),
    length vals = 40%nat -> vals_ev vals 0 = sp0 -> vals_ev vals 2 = code ->
    regs_ok (ENV vals) x_sr R -> know_ok RSEGS (ENV vals) M (ax_kn true true) ->
    (bv_unsigned (vals_ev vals 4) - 7425016 = Z.of_nat (length pending))%Z ->
    (Z.of_nat (length pending) <= 1024)%Z ->
    rdn RSEGS M (Z_to_bv 64 7425016) (length pending) = Some pending ->
    fd_lookup (m_fds mo) (Z_to_bv 64 1) = Some (FdChannel (Z_to_bv 64 1)) ->
    m_channel_reader mo = true ->
    lzok RSEGS L S Zr (mkCfg msF mo) -> restrict L S msF = mkst R (Z_to_bv 64 AEXIT) M (seg_rom RSEGS) ->
    realizes RSEGS (mkCfg msF mo)
      (t_emit (map (WriteEv (Z_to_bv 64 1)) pending) (t_exit (bv_and code (Z_to_bv 64 255)) (m_fs mo))).
  Proof.
    intros vals R M msF mo pending code HL P0 P2 HR HK LEN MAX RDP Hfd1 Hrd1 OK RS.
    pose proof (know_nth RSEGS _ _ (ax_kn true true) 1%nat _ HK eq_refl) as Hrg.
    cbn [kentry_ok edenot ev ENV] in Hrg. rewrite P0 in Hrg.
    unfold ASP_LO, ASP_HI in Hrg. pose proof (u64_range sp0) as Hsp.
    pose proof (x_regions_flat vals P0 ltac:(unfold ASP_LO; lia) ltac:(unfold ASP_HI; lia)) as RF.
    pose proof (x_regions_denot vals P0 ltac:(unfold ASP_LO; lia)) as RD.
    pose proof x_itinerary_flush as (PC1 & SC1 & CC1 & CC2i & KR1 & PC2 & SC2 & CC2 & CC3i & KR2 &
                                     PC3 & SC3 & CC3 & CC4i & KR3 & PC4 & SC4 & CC4 & SCALL & PC5 & SC5 & CC5).
    (* run 1: AEXIT to the exit-lock CAS *)
    eapply (rz_run_lf_lazy RSEGS L S Zr XFUEL XSTOPS scr0 AEXIT x_sr (ax_kn true true) 40
              (fst (fst rX1f)) (snd (fst rX1f)) (snd rX1f) (fst (fst cX1f)) (snd (fst cX1f)) (snd cX1f)
              (ENV vals) M (seg_rom RSEGS) R msF mo);
      [ vm_cast_no_check (@eq_refl _ rX1f) | vm_cast_no_check (@eq_refl _ cX1f)
      | exact HR | exact HK | rewrite SC1; constructor | rewrite CC1; exact (Forall_nil _) | exact OK | exact RS | ].
    clear HR HK RS OK. intros R1 M1 msF1 mo1 HR HK EQ1 LF1 OK1 SB1 HS1 RS1.
    pose proof (log_covered_frame (ENV vals) M x_regions _ x_covX1 RF LF1) as F1.
    rewrite <- EQ1, RD in F1. clear EQ1 LF1.
    change (s_regs (fst (fst rX1f))) with srX1f in HR. change (fst (fst cX1f)) with knX1f in HK.
    rewrite PC1 in RS1.
    replace (Z_to_bv 64 1656092) with (0x19451c : word) in RS1 by (apply bv_eq; reflexivity).
    pose proof (kread_rdn RSEGS (ENV vals) M1 knX1f (ELit 0) 0x714648 4 _ HK KR1 ltac:(lia) ltac:(lia)
                  ltac:(unfold flat, estart; cbn [a_base a_off edenot];
                        change (bv_unsigned (Z_to_bv 64 0)) with 0%Z; lia)) as Mlock.
    rewrite adenot_lit0 in Mlock. cbn [edenot] in Mlock.
    eapply (rz_msteps_lazy_mkst RSEGS L S Zr); [exact OK1 | exact RS1 | |].
    { apply (cas_exit_lock R1 M1 (seg_rom RSEGS) (getr R1 12));
        [regv HR (13:reg); reflexivity | regv HR (11:reg); reflexivity | reflexivity | exact Mlock]. }
    clear Mlock. intros msF2 mo2 OK2 SB2 HS2 RS2.
    (* MEASURED, round 6: RS2 HAS pc `1656104` as a BARE word literal and the run WANTS
       `Z_to_bv 64 1656104`; every other field of the four already matches (msF2, the
       double regupd, the wbytes at 7423560, seg_rom).  Round 4 guessed this backwards.
       This is the donor's mirrored line, literal -> Z_to_bv. *)
    replace (1656104 : word) with (Z_to_bv 64 1656104) in RS2 by (apply bv_eq; reflexivity).
    assert (HR2 : regs_ok (ENV vals) srX2if (regupd (regupd R1 14 (Z_to_bv 64 0)) 15 (Z_to_bv 64 0))).
    { change srX2if with (sr_upd (sr_upd srX1f (ridx 14) (ELit 0%Z)) (ridx 15) (ELit 0%Z)).
      apply regs_ok_set; [apply regs_ok_set; [exact HR | discriminate | reflexivity] | discriminate | reflexivity]. }
    assert (HK2 : know_ok RSEGS (ENV vals) (wbytes M1 (Z_to_bv 64 0x714648) (word_to_le_bytes 4 (getr R1 12))) knX2if).
    { change knX2if with (fst (fst cX2if)).
      apply (one_carry_ok (ENV vals) M1 knX1f 0x714648 4 (sr_get srX1f 12) (getr R1 12) (fst (fst cX2if)) (snd cX2if));
        [ vm_cast_no_check (@eq_refl _ cX2if) | exact HK | symmetry; apply HR | lia | cbn; lia | lia ]. }
    pose proof (frame_wbytes_lit M1 0x714648 4 (getr R1 12) ltac:(lia) ltac:(cbn; lia)) as F1c.
    clear HR HK.
    (* run 2: the CAS return to the mutex lock *)
    eapply (rz_run_lf_lazy RSEGS L S Zr XFUEL XSTOPS scr0 0x194528 srX2if knX2if 40
              (fst (fst rX2f)) (snd (fst rX2f)) (snd rX2f) (fst (fst cX2f)) (snd (fst cX2f)) (snd cX2f)
              (ENV vals) (wbytes M1 (Z_to_bv 64 0x714648) (word_to_le_bytes 4 (getr R1 12)))
              (seg_rom RSEGS) (regupd (regupd R1 14 (Z_to_bv 64 0)) 15 (Z_to_bv 64 0)) msF2 mo2);
      [ vm_cast_no_check (@eq_refl _ rX2f) | vm_cast_no_check (@eq_refl _ cX2f)
      | exact HR2 | exact HK2 | rewrite SC2; exact (Forall_nil _) | rewrite CC2; exact (Forall_nil _) | exact OK2
      | exact RS2 | ].
    clear HR2 HK2 RS2 OK2. intros R2 M2 msF3 mo3 HR HK EQ2 LF2 OK3 SB3 HS3 RS3.
    pose proof (log_covered_frame (ENV vals) (wbytes M1 (Z_to_bv 64 0x714648) (word_to_le_bytes 4 (getr R1 12)))
                 x_regions _ x_covX2 RF LF2) as F2.
    rewrite <- EQ2, RD in F2. clear EQ2 LF2.
    change (s_regs (fst (fst rX2f))) with srX2f in HR. change (fst (fst cX2f)) with knX2f in HK.
    rewrite PC2 in RS3.
    replace (Z_to_bv 64 490388) with (0x77b94 : word) in RS3 by (apply bv_eq; reflexivity).
    pose proof (kread_rdn RSEGS (ENV vals) M2 knX2f (ELit 0) 0x1bdaf0 8 _ HK KR2 ltac:(lia) ltac:(lia)
                  ltac:(unfold flat, estart; cbn [a_base a_off edenot];
                        change (bv_unsigned (Z_to_bv 64 0)) with 0%Z; lia)) as Mmu1.
    rewrite adenot_lit0 in Mmu1. cbn [edenot] in Mmu1.
    eapply (rz_msteps_lazy_mkst RSEGS L S Zr); [exact OK3 | exact RS3 | |].
    { apply (cas_mu_lock R2 M2 (seg_rom RSEGS) (edenot (ENV vals) (sr_get srX2f 12)));
        [regv HR (24:reg); reflexivity | apply HR | exact Mmu1]. }
    clear Mmu1. intros msF4 mo4 OK4 SB4 HS4 RS4.
    replace (490400 : word) with (Z_to_bv 64 490400) in RS4 by (apply bv_eq; reflexivity).
    assert (HR3 : regs_ok (ENV vals) srX3if
                    (regupd (regupd R2 13 (edenot (ENV vals) (sr_get srX2f 12))) 15 (Z_to_bv 64 0))).
    { change srX3if with (sr_upd (sr_upd srX2f (ridx 13) (sr_get srX2f 12)) (ridx 15) (ELit 0%Z)).
      apply regs_ok_set; [apply regs_ok_set; [exact HR | discriminate | reflexivity] | discriminate | reflexivity]. }
    assert (HK3 : know_ok RSEGS (ENV vals) (wbytes M2 (Z_to_bv 64 0x1bdaf0) (word_to_le_bytes 8 (getr R2 14))) knX3if).
    { change knX3if with (fst (fst cX3if)).
      apply (one_carry_ok (ENV vals) M2 knX2f 0x1bdaf0 8 (sr_get srX2f 14) (getr R2 14) (fst (fst cX3if)) (snd cX3if));
        [ vm_cast_no_check (@eq_refl _ cX3if) | exact HK | symmetry; apply HR | lia | cbn; lia | lia ]. }
    pose proof (frame_wbytes_lit M2 0x1bdaf0 8 (getr R2 14) ltac:(lia) ltac:(cbn; lia)) as F2c.
    clear HR HK.
    (* run 3: through the shadow-dropping carry.  rX3g starts from knX3g = filter x3_core knX3if
       (AsExitDefs.v:93, :98) and its carry is a carry_keep (:103), so this run takes
       rz_run_lf_lazy_keep (As/AsCarryKeep.v:52), not the plain lemma.  x3_facts_f (:112) is a
       CLOSED fact with no arguments, and its three conjuncts are exactly the three side
