              (fst (fst rX3g)) (snd (fst rX3g)) (snd rX3g) (fst (fst cX3g)) (snd (fst cX3g)) (snd cX3g)
              (ENV vals) (wbytes M2 (Z_to_bv 64 0x1bdaf0) (word_to_le_bytes 8 (getr R2 14)))
