    change (s_regs (fst (fst rX3g))) with srX3f in HR.
    rewrite PC3 in RS5.
    replace (Z_to_bv 64 491268) with (0x77f04 : word) in RS5 by (apply bv_eq; reflexivity).
    pose proof (kread_rdn RSEGS (ENV vals) M3 knX3f (ELit 0) 0x1bdaf0 8 _ HKf KR3 ltac:(lia) ltac:(lia)
                  ltac:(unfold flat, estart; cbn [a_base a_off edenot];
                        change (bv_unsigned (Z_to_bv 64 0)) with 0%Z; lia)) as Mmu2.
    rewrite adenot_lit0 in Mmu2. cbn [edenot] in Mmu2.
    eapply (rz_msteps_lazy_mkst RSEGS L S Zr); [exact OK5 | exact RS5 | |].
    { apply (cas_mu_unlock R3 M3 (seg_rom RSEGS) (edenot (ENV vals) (sr_get srX3f 10)));
        [regv HR (24:reg); reflexivity | apply HR | exact Mmu2]. }
    clear Mmu2. intros msF6 mo6 OK6 SB6 HS6 RS6.
    replace (491280 : word) with (Z_to_bv 64 491280) in RS6 by (apply bv_eq; reflexivity).
    assert (HR4 : regs_ok (ENV vals) srX4if
                    (regupd (regupd R3 6 (edenot (ENV vals) (sr_get srX3f 10))) 7 (Z_to_bv 64 0))).
    { change srX4if with (sr_upd (sr_upd srX3f (ridx 6) (sr_get srX3f 10)) (ridx 7) (ELit 0%Z)).
      apply regs_ok_set; [apply regs_ok_set; [exact HR | discriminate | reflexivity] | discriminate | reflexivity]. }
    assert (HK4 : know_ok RSEGS (ENV vals) (wbytes M3 (Z_to_bv 64 0x1bdaf0) (word_to_le_bytes 8 (getr R3 5))) knX4if).
    { change knX4if with (fst (fst cX4if)).
      apply (one_carry_ok (ENV vals) M3 knX3f 0x1bdaf0 8 (sr_get srX3f 5) (getr R3 5) (fst (fst cX4if)) (snd cX4if));
        [ vm_cast_no_check (@eq_refl _ cX4if) | exact HKf | symmetry; apply HR | lia | cbn; lia | lia ]. }
    pose proof (frame_wbytes_lit M3 0x1bdaf0 8 (getr R3 5) ltac:(lia) ltac:(cbn; lia)) as F3c.
    clear HR HK HKf.
    (* run 4: to the stdio entry *)
    eapply (rz_run_lf_lazy RSEGS L S Zr XFUEL XSTOPS scr0 0x77f10 srX4if knX4if 40
              (fst (fst rX4f)) (snd (fst rX4f)) (snd rX4f) (fst (fst cX4f)) (snd (fst cX4f)) (snd cX4f)
              (ENV vals) (wbytes M3 (Z_to_bv 64 0x1bdaf0) (word_to_le_bytes 8 (getr R3 5)))
              (seg_rom RSEGS) (regupd (regupd R3 6 (edenot (ENV vals) (sr_get srX3f 10))) 7 (Z_to_bv 64 0)) msF6 mo6);
      [ vm_cast_no_check (@eq_refl _ rX4f) | vm_cast_no_check (@eq_refl _ cX4f)
      | exact HR4 | exact HK4 | rewrite SC4; exact (Forall_nil _) | rewrite CC4; exact (Forall_nil _) | exact OK6 | exact RS6 | ].
    clear HR4 HK4 RS6 OK6. intros R4 M4 msF7 mo7 HR HK EQ4 LF4 OK7 SB7 HS7 RS7.
    pose proof (log_covered_frame (ENV vals) (wbytes M3 (Z_to_bv 64 0x1bdaf0) (word_to_le_bytes 8 (getr R3 5)))
                 x_regions _ x_covX4 RF LF4) as F4.
    rewrite <- EQ4, RD in F4. clear EQ4 LF4.
    change (s_regs (fst (fst rX4f))) with srX4f in HR. change (fst (fst cX4f)) with knX4f in HK.
    rewrite PC4 in RS7.
    assert (FM : frame_mod M M4 (x_regions_w ++ [(Z_to_bv 64 0x714648, 4%Z)] ++ x_regions_w
                                 ++ [(Z_to_bv 64 0x1bdaf0, 8%Z)] ++ x_regions_w
                                 ++ [(Z_to_bv 64 0x1bdaf0, 8%Z)] ++ x_regions_w)).
    { eapply frame_mod_trans; [exact F1|]. eapply frame_mod_trans; [exact F1c|].
      eapply frame_mod_trans; [exact F2|]. eapply frame_mod_trans; [exact F2c|].
      eapply frame_mod_trans; [exact F3|]. eapply frame_mod_trans; [exact F3c| exact F4]. }
    assert (RDP4 : rdn RSEGS M4 (Z_to_bv 64 7425016) (length pending) = Some pending).
    { rewrite <- RDP. apply (frame_mod_rdn RSEGS M M4 _ (length pending) (Z_to_bv 64 7425016) FM).
      (* FM's region list is seven segments, not one: four copies of x_regions_w and the three
         CAS cells.  Frame.v:25 outside_app is an iff, so split it down to the leaves; the
         x_regions_w leaves are x_regions_buf and the three literal cells are the AsTailExit.v:52
         idiom (the buffer is 0x711bf8..0x711ff8 for <= 1024 pending bytes, the cells are
         0x714648+4 and 0x1bdaf0+8, disjoint). *)
      - intros i Hi. rewrite u64_lit by lia.
        repeat (apply outside_app; split).
        (* Round 18 printed the seven leaves in this order: x_regions_w, cell, x_regions_w,
           cell, x_regions_w, cell, x_regions_w.  Addressed by position rather than by a
           `first`, so a failure names the tactic instead of saying "No applicable tactic".
           x_regions_buf takes TWO premises, not three (round 19): its first is the single
           conjunction 0 <= i < 1024 and its second is the sp0 bound, which Hrg carries. *)
        1,3,5,7: apply x_regions_buf;
                   [ lia | try unfold ASP_LO in *; try unfold ASP_HI in *; lia ].
        all: cbn [outside]; unfold in_rng; rewrite !u64_lit by lia; lia.
      - rewrite u64_lit by lia. lia. }
    pose proof (u64_range (vals_ev vals 4)) as H4r.
    rewrite <- (app_nil_r pending).
    apply (stdio_call_sound vals (blobs_ev []) srX4f knX4f R4 M4 L S Zr msF7 mo7 x_scf pending [] _ HR HK
             (eq_trans (f_equal (fun n => stdio_call n srX4f knX4f) HL) SCALL));
      cbn [sc_f sc_fd sc_ret sc_wb sc_wp sc_bufp sc_bufsz sc_s sc_l sc_sp sc_sr sc_kn x_scf length
           edenot ev ENV Z.of_nat Pos.of_succ_nat Pos.succ];
      rewrite ?P0.
    all: try change (bv_unsigned (Z_to_bv 64 7425016)) with 7425016%Z.
    all: try change (bv_unsigned (Z_to_bv 64 0)) with 0%Z.
    - lia.
    - lia.
    - lia.
    - reflexivity.
    - cbn [length]. lia.
    - left. rewrite alu_add, vadd_wZ. unorm. lia.
    - left. rewrite alu_add, vadd_wZ. unorm. lia.
    - lia.
    - exact RDP4.
    - reflexivity.
    - rewrite (same_but_materialized_fds _ _ SB7), (same_but_materialized_fds _ _ SB6),
              (same_but_materialized_fds _ _ SB5), (same_but_materialized_fds _ _ SB4),
              (same_but_materialized_fds _ _ SB3), (same_but_materialized_fds _ _ SB2),
              (same_but_materialized_fds _ _ SB1). exact Hfd1.
    (* LPS 75d69e00: the reader premise, transported through every materialization between the
       top and the write -- the fds line above with one name changed. *)
    - rewrite (same_but_materialized_reader _ _ SB7), (same_but_materialized_reader _ _ SB6),
              (same_but_materialized_reader _ _ SB5), (same_but_materialized_reader _ _ SB4),
              (same_but_materialized_reader _ _ SB3), (same_but_materialized_reader _ _ SB2),
              (same_but_materialized_reader _ _ SB1). exact Hrd1.
    - exact OK7.
    - exact RS7.
    - apply t_emit_has_nil.
    - clear HR HK. intros R5 M5 msF8 mo8 HR HK OK8 SB8 HS8 RS8.
      set (vals' := vals ++ junk_vals R5) in *.
      change (Env (vals_ev vals') (blobs_ev [])) with (ENV vals') in HR, HK.
      eapply (rz_run_lazy RSEGS L S Zr XFUEL XSTOPS scr0 (sc_ret x_scf) (sc_sr x_scf) (sc_kn x_scf) 72
                (fst (fst rX5f)) (snd (fst rX5f)) (snd rX5f) (fst (fst cX5f)) (snd (fst cX5f)) (snd cX5f)
                (ENV vals') M5 (seg_rom RSEGS) R5 msF8 mo8);
        [ vm_cast_no_check (@eq_refl _ rX5f) | vm_cast_no_check (@eq_refl _ cX5f)
        | exact HR | exact HK | rewrite SC5; exact (Forall_nil _) | rewrite CC5; exact (Forall_nil _) | exact OK8 | exact RS8 | ].
      clear HR HK. intros R6 M6 msF9 mo9 HR HK EQ6 OK9 SB9 HS9 RS9. rewrite PC5 in RS9.
      rewrite <- (same_but_materialized_fs _ _ SB1), <- (same_but_materialized_fs _ _ SB2),
              <- (same_but_materialized_fs _ _ SB3), <- (same_but_materialized_fs _ _ SB4),
              <- (same_but_materialized_fs _ _ SB5), <- (same_but_materialized_fs _ _ SB6),
              <- (same_but_materialized_fs _ _ SB7), <- (same_but_materialized_fs _ _ SB8),
              <- (same_but_materialized_fs _ _ SB9).
      eapply (rz_exit_at_lazy RSEGS L S Zr msF9 R6 (Z_to_bv 64 AEXIT_ECALL) M6 (seg_rom RSEGS) mo9 ECALLW code);
        [ vm_compute; reflexivity | apply is_ecall_ECALLW | exact OK9 | exact RS9 | reflexivity
        | left; regv HR (17:reg); reflexivity | regv HR (10:reg) ].
      change (edenot (ENV vals') (EVar 2)) with (vals_ev vals' 2). subst vals'.
      rewrite vals_ev_app_l by (rewrite HL; lia). exact P2.
  Qed.

