  (* LPS 75d69e00, the channel-reader premise, SECOND of the two sites.  ax_sound_flush now
     carries [m_channel_reader mo = true], so this wrapper's replayed application of it was one
     argument short ("The 22nd term has type lzok ... which should be a subtype of
     m_channel_reader mo = true", a farm round).  The statement is written out
     with the premise in the same slot as above -- after fd_lookup, before lzok -- and its OLD
     arm for the About faithfulness control is g3notes/bjrb-asexit-statements.txt, captured
     before any edit.  Nothing else in it moves.
     DONOR for the proof shape (rule 23c): a donor tree:
     projects/openssl/echconfiglist_parser/proofs/lib/Both/AsExit/AsExit.v:753-786
     (as_exit_flush2), which already carries Hrd1 in the same slot.  It differs in having a
     byte-index parameter bi and a two-way split on it; this tree has neither, so the split is
     dropped and ax_sound_flush replaces ax_sound_2zf/2nf. *)
  Theorem as_exit_flush : forall regs mem msF mo (sp code we re ro : word) (tid can wp : Z) (pending : list byte),
    axH2 mem sp tid can we re ro ->
    rdn RSEGS mem (Z_to_bv 64 1810464) 8 = Some (word_to_le_bytes 8 (Z_to_bv 64 wp)) ->
    cells_ok mem ax_flush_cells ->
    (7425017 <= wp <= 7426040)%Z ->
    (wp - 7425016 = Z.of_nat (length pending))%Z ->
    rdn RSEGS mem (Z_to_bv 64 7425016) (length pending) = Some pending ->
    getr regs 2 = sp -> getr regs 4 = Z_to_bv 64 7291864 -> getr regs 10 = code ->
    fd_lookup (m_fds mo) (Z_to_bv 64 1) = Some (FdChannel (Z_to_bv 64 1)) ->
    m_channel_reader mo = true ->
    lzok RSEGS L S Zr (mkCfg msF mo) ->
    restrict L S msF = mkst regs (Z_to_bv 64 AEXIT) mem (seg_rom RSEGS) ->
    realizes RSEGS (mkCfg msF mo)
      (t_emit (map (WriteEv (Z_to_bv 64 1)) pending) (t_exit (bv_and code (Z_to_bv 64 255)) (m_fs mo))).
Proof.
    intros regs mem msF mo sp code we re ro tid can wp pending XH Xwp Xfc Hwp LEN RDP R2 R4 R10 Hfd1 Hrd1 OK RS.
    assert (Z0 : bv_unsigned (Z_to_bv 64 0) = 0%Z) by reflexivity.
    assert (E4 : ev (ENV (x_vals regs sp tid code can wp we re ro)) 4 = Z_to_bv 64 wp)
      by reflexivity.
    apply (ax_sound_flush sp L S Zr (x_vals regs sp tid code can wp we re ro)
             regs mem msF mo pending code);
      [ reflexivity | reflexivity | reflexivity | apply x_regs_ok; assumption
      | | cbn [vals_ev x_vals nth app]; rewrite u64_lit by lia; lia
      | lia | exact RDP | exact Hfd1 | exact Hrd1 | exact OK | exact RS ].
    (* ax_kn true true unfolds to BIGLIST ++ ([the two wp entries] ++ kn_cells ax_flush_cells)
       ++ kn_cells ax_lit_cells2 (printed by the Bs twin's a farm round), which is exactly
       x_know_ok_common's BIGLIST ++ extra ++ kn_cells cells with cells = ax_lit_cells2. *)
    unfold ax_kn.
    apply (x_know_ok_common ax_lit_cells2 true); [vm_compute; reflexivity | exact XH |].
    apply (proj2 (know_ok_app RSEGS _ _ _ _)). split;
      [| apply cells_know; [vm_compute; reflexivity | exact Xfc]].
    repeat (apply Forall_cons); [ .. | apply Forall_nil].
    - kw_var Z0 E4 Xwp.
    - apply krange_intro. cbn [edenot]. rewrite E4, u64_lit by lia. lia.
  Qed.

